/**
 * A query optimizer that (partially) normalizes query models to a canonical form. Note: this implementation does not
 * yet cover all query node types.
 *
 * @author Arjohn Kampman
 */
public class QueryModelNormalizerOptimizer extends AbstractSimpleQueryModelVisitor<RuntimeException>
		implements QueryOptimizer {

	private static final ThreadLocal<QueryAlgebraBindingAnalysis> CURRENT_ANALYSIS = new ThreadLocal<>();

	public QueryModelNormalizerOptimizer() {
		super(false);
	}

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		QueryAlgebraBindingAnalysis previous = CURRENT_ANALYSIS.get();
		CURRENT_ANALYSIS.set(QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr, bindings));
		try {
			// Visit this instance so subclasses overriding the public visitor hooks remain in the dispatch path.
			tupleExpr.visit(this);
		} finally {
			if (previous == null) {
				CURRENT_ANALYSIS.remove();
			} else {
				CURRENT_ANALYSIS.set(previous);
			}
		}
	}

	@Override
	public void meet(Join join) {
		super.meet(join);

		TupleExpr leftArg = join.getLeftArg();
		TupleExpr rightArg = join.getRightArg();

		if (leftArg instanceof EmptySet || rightArg instanceof EmptySet) {
			replacePreservingScope(join, new EmptySet());
		} else if (leftArg instanceof SingletonSet) {
			replacePreservingScope(join, rightArg);
		} else if (rightArg instanceof SingletonSet) {
			replacePreservingScope(join, leftArg);
		} else if (leftArg instanceof Union union && canDistribute(union, rightArg)) {
			// sort unions above joins
			Join leftJoin = new Join(union.getLeftArg(), rightArg.clone());
			Join rightJoin = new Join(union.getRightArg(), rightArg.clone());
			Union newUnion = new Union(leftJoin, rightJoin);
			newUnion.setVariableScopeChange(union.isVariableScopeChange() || join.isVariableScopeChange());
			replacePreservingScope(join, newUnion);
			invalidateAnalysis();
			newUnion.visit(this);
		} else if (rightArg instanceof Union union && canDistribute(union, leftArg)) {
			// sort unions above joins
			Join leftJoin = new Join(leftArg.clone(), union.getLeftArg());
			Join rightJoin = new Join(leftArg.clone(), union.getRightArg());
			Union newUnion = new Union(leftJoin, rightJoin);
			newUnion.setVariableScopeChange(union.isVariableScopeChange() || join.isVariableScopeChange());
			replacePreservingScope(join, newUnion);
			invalidateAnalysis();
			newUnion.visit(this);
		} else if (leftArg instanceof LeftJoin leftJoin && isWellDesigned(leftJoin, rightArg)) {
			// sort left join above normal joins
			boolean scopeChange = leftJoin.isVariableScopeChange() || join.isVariableScopeChange();
			replacePreservingScope(join, leftJoin);
			join.setLeftArg(leftJoin.getLeftArg());
			leftJoin.setLeftArg(join);
			leftJoin.setVariableScopeChange(scopeChange);
			invalidateAnalysis();
			leftJoin.visit(this);
		} else if (rightArg instanceof LeftJoin leftJoin && isWellDesigned(leftJoin, leftArg)) {
			// sort left join above normal joins
			boolean scopeChange = leftJoin.isVariableScopeChange() || join.isVariableScopeChange();
			replacePreservingScope(join, leftJoin);
			join.setRightArg(leftJoin.getLeftArg());
			leftJoin.setLeftArg(join);
			leftJoin.setVariableScopeChange(scopeChange);
			invalidateAnalysis();
			leftJoin.visit(this);
		}
	}

	@Override
	public void meet(LeftJoin leftJoin) {
		super.meet(leftJoin);

		TupleExpr leftArg = leftJoin.getLeftArg();
		TupleExpr rightArg = leftJoin.getRightArg();
		ValueExpr condition = leftJoin.getCondition();

		if (leftArg instanceof EmptySet) {
			replacePreservingScope(leftJoin, leftArg);
		} else if (rightArg instanceof EmptySet) {
			replacePreservingScope(leftJoin, leftArg);
		} else if (rightArg instanceof SingletonSet) {
			replacePreservingScope(leftJoin, leftArg);
		} else if (condition instanceof ValueConstant) {
			boolean conditionValue = QueryEvaluationUtility
					.getEffectiveBooleanValue(((ValueConstant) condition).getValue())
					.orElse(false);

			if (!conditionValue) {
				// Constraint is always false
				replacePreservingScope(leftJoin, leftArg);
			} else {
				leftJoin.setCondition(null);
				invalidateAnalysis();
			}
		}
	}

	@Override
	public void meet(Union union) {
		super.meet(union);

		TupleExpr leftArg = union.getLeftArg();
		TupleExpr rightArg = union.getRightArg();

		if (leftArg instanceof EmptySet) {
			replacePreservingScope(union, rightArg);
		} else if (rightArg instanceof EmptySet) {
			replacePreservingScope(union, leftArg);
		}
	}

	@Override
	public void meet(Difference difference) {
		super.meet(difference);

		TupleExpr leftArg = difference.getLeftArg();
		TupleExpr rightArg = difference.getRightArg();

		if (leftArg instanceof EmptySet) {
			replacePreservingScope(difference, leftArg);
		} else if (rightArg instanceof EmptySet) {
			replacePreservingScope(difference, leftArg);
		} else if (leftArg instanceof SingletonSet && rightArg instanceof SingletonSet) {
			// MINUS only removes rows that share a variable with a right row, so the empty solution survives.
			replacePreservingScope(difference, leftArg);
		}
	}

	@Override
	public void meet(Intersection intersection) {
		super.meet(intersection);

		TupleExpr leftArg = intersection.getLeftArg();
		TupleExpr rightArg = intersection.getRightArg();

		if (leftArg instanceof EmptySet || rightArg instanceof EmptySet) {
			replacePreservingScope(intersection, new EmptySet());
		}
	}

	@Override
	protected void meetUnaryTupleOperator(UnaryTupleOperator node) {
		super.meetUnaryTupleOperator(node);

		if (node.getArg() instanceof EmptySet
				// An implicit group (no GROUP BY) yields one aggregate row even over empty input.
				&& !(node instanceof Group group && group.getGroupBindingNames().isEmpty())) {
			replacePreservingScope(node, node.getArg());
		}
	}

	@Override
	public void meet(Filter node) {
		super.meet(node);

		TupleExpr arg = node.getArg();
		ValueExpr condition = node.getCondition();

		if (arg instanceof EmptySet) {
			// see #meetUnaryTupleOperator
		} else if (condition instanceof ValueConstant) {
			boolean conditionValue = QueryEvaluationUtility
					.getEffectiveBooleanValue(((ValueConstant) condition).getValue())
					.orElse(false);

			if (!conditionValue) {
				// Constraint is always false
				replacePreservingScope(node, new EmptySet());
			} else {
				replacePreservingScope(node, arg);
			}
		}
	}

	@Override
	public void meet(Or or) {
		super.meet(or);

		if (or.getLeftArg().equals(or.getRightArg())
				&& AlgebraEvaluationSafety.isRepeatable(or.getLeftArg())
				&& AlgebraEvaluationSafety.isRepeatable(or.getRightArg())) {
			or.replaceWith(or.getLeftArg());
			invalidateAnalysis();
		}
	}

	@Override
	public void meet(And and) {
		super.meet(and);

		if (and.getLeftArg().equals(and.getRightArg())
				&& AlgebraEvaluationSafety.isRepeatable(and.getLeftArg())
				&& AlgebraEvaluationSafety.isRepeatable(and.getRightArg())) {
			and.replaceWith(and.getLeftArg());
			invalidateAnalysis();
		}
	}

	private boolean canDistribute(Union union, TupleExpr repeatedArgument) {
		if (!AlgebraEvaluationSafety.isRepeatable(repeatedArgument)
				|| !AlgebraEvaluationSafety.isRepeatable(union.getLeftArg())
				|| !AlgebraEvaluationSafety.isRepeatable(union.getRightArg())) {
			return false;
		}
		QueryAlgebraBindingAnalysis analysis = CURRENT_ANALYSIS.get();
		if (analysis == null) {
			return true;
		}

		QueryAlgebraBindingAnalysis.ReadOnlyContext leftContext = analysis.contextAt(union.getLeftArg());
		QueryAlgebraBindingAnalysis.ReadOnlyContext rightContext = analysis.contextAt(union.getRightArg());
		QueryAlgebraBindingAnalysis.ReadOnlyContext repeatedContext = analysis.contextAt(repeatedArgument);
		QueryAlgebraBindingAnalysis.OutputFacts leftFacts = analysis.outputFacts(union.getLeftArg(), leftContext);
		QueryAlgebraBindingAnalysis.OutputFacts rightFacts = analysis.outputFacts(union.getRightArg(), rightContext);
		QueryAlgebraBindingAnalysis.OutputFacts repeatedFacts = analysis.outputFacts(repeatedArgument, repeatedContext);
		return leftContext.scopeIdentity() == rightContext.scopeIdentity()
				&& leftContext.scopeIdentity() == repeatedContext.scopeIdentity()
				&& leftFacts.possibleOutputsKnown() && leftFacts.guaranteedOutputsKnown()
				&& rightFacts.possibleOutputsKnown() && rightFacts.guaranteedOutputsKnown()
				&& repeatedFacts.possibleOutputsKnown() && repeatedFacts.guaranteedOutputsKnown();
	}

	/**
	 * Checks whether moving this left join above its parent join would expose its right argument to new bindings.
	 */
	private boolean isWellDesigned(LeftJoin leftJoin, TupleExpr newlyJoinedInput) {
		QueryAlgebraBindingAnalysis analysis = CURRENT_ANALYSIS.get();
		if (analysis == null) {
			return isWellDesignedWithoutBindingAnalysis(leftJoin);
		}
		if (!AlgebraEvaluationSafety.isRepeatable(leftJoin)
				|| !AlgebraEvaluationSafety.isRepeatable(newlyJoinedInput)) {
			return false;
		}

		QueryAlgebraBindingAnalysis.ReadOnlyContext leftContext = analysis.contextAt(leftJoin.getLeftArg());
		QueryAlgebraBindingAnalysis.ReadOnlyContext inputContext = analysis.contextAt(newlyJoinedInput);
		QueryAlgebraBindingAnalysis.ReadOnlyContext rightContext = analysis.contextAt(leftJoin.getRightArg());
		QueryAlgebraBindingAnalysis.OutputFacts leftFacts = analysis.outputFacts(leftJoin.getLeftArg(), leftContext);
		QueryAlgebraBindingAnalysis.OutputFacts rightFacts = analysis.outputFacts(leftJoin.getRightArg(), rightContext);
		QueryAlgebraBindingAnalysis.OutputFacts inputFacts = analysis.outputFacts(newlyJoinedInput, inputContext);
		if (leftContext.scopeIdentity() != inputContext.scopeIdentity()
				|| !leftFacts.possibleOutputsKnown() || !leftFacts.guaranteedOutputsKnown()
				|| !rightFacts.possibleOutputsKnown()
				|| !inputFacts.possibleOutputsKnown()) {
			return false;
		}

		Set<String> overlappingNames = new HashSet<>(rightFacts.possibleOutputs());
		overlappingNames.retainAll(inputFacts.possibleOutputs());
		if (overlappingNames.isEmpty()) {
			return bindingsStableAcrossReorder(leftJoin, newlyJoinedInput, overlappingNames, analysis);
		}

		Set<String> guaranteedByLeft = new HashSet<>(leftFacts.guaranteedOutputs());
		Set<String> inheritedAndRetained = new HashSet<>(leftFacts.inheritedInputNames());
		inheritedAndRetained.retainAll(leftFacts.retainedInputNames());
		inheritedAndRetained.removeAll(leftFacts.overwrittenInputNames());
		guaranteedByLeft.addAll(inheritedAndRetained);
		Set<String> overwrittenOverlaps = new HashSet<>(rightFacts.overwrittenInputNames());
		overwrittenOverlaps.retainAll(overlappingNames);
		return guaranteedByLeft.containsAll(overlappingNames) && overwrittenOverlaps.isEmpty()
				&& bindingsStableAcrossReorder(leftJoin, newlyJoinedInput, overlappingNames, analysis);
	}

	private boolean bindingsStableAcrossReorder(LeftJoin leftJoin, TupleExpr newlyJoinedInput,
			Set<String> overlappingNames, QueryAlgebraBindingAnalysis analysis) {
		if (!(leftJoin.getParentNode()instanceof Join parentJoin)) {
			return false;
		}
		boolean optionalWasLeft = parentJoin.getLeftArg() == leftJoin;
		if (!optionalWasLeft && parentJoin.getRightArg() != leftJoin) {
			return false;
		}

		TupleExpr siblingCopy = newlyJoinedInput.clone();
		TupleExpr optionalLeftCopy = leftJoin.getLeftArg().clone();
		Join movedJoin = optionalWasLeft
				? new Join(optionalLeftCopy, siblingCopy)
				: new Join(siblingCopy, optionalLeftCopy);
		movedJoin.setVariableScopeChange(parentJoin.isVariableScopeChange());
		LeftJoin movedLeftJoin = leftJoin.clone();
		movedLeftJoin.setLeftArg(movedJoin);
		movedLeftJoin.setVariableScopeChange(
				leftJoin.isVariableScopeChange() || parentJoin.isVariableScopeChange());

		QueryAlgebraBindingAnalysis.ReadOnlyContext parentInput = analysis.contextAt(parentJoin);
		QueryAlgebraBindingAnalysis.ReadOnlyContext sourceLeftJoinInput = analysis.contextAt(leftJoin);
		if (sourceLeftJoinInput.scopeIdentity() != parentInput.scopeIdentity()) {
			return false;
		}

		List<ExpressionFrame> sourceFrames = expressionFrames(analysis, leftJoin.getRightArg(),
				analysis.contextAt(leftJoin.getRightArg()));
		if (leftJoin.hasCondition()) {
			QueryAlgebraBindingAnalysis.ReadOnlyContext conditionInput = analysis.contextAt(leftJoin.getCondition());
			sourceFrames.add(new ExpressionFrame(leftJoin.getCondition(), conditionInput,
					analysis.dependencies(leftJoin.getCondition(), conditionInput)));
		}
		List<ExpressionFrame> movedFrames = new ArrayList<>();
		QueryAlgebraBindingAnalysis.ReadOnlyContext[] movedRightInput = new QueryAlgebraBindingAnalysis.ReadOnlyContext[1];
		QueryAlgebraBindingAnalysis.ReadOnlyContext[] movedConditionInput = new QueryAlgebraBindingAnalysis.ReadOnlyContext[1];
		QueryAlgebraBindingAnalysis.OutputFacts[] siblingFacts = new QueryAlgebraBindingAnalysis.OutputFacts[1];
		analysis.visitScoped(movedLeftJoin, parentInput, (node, nodeInput) -> {
			if (node == siblingCopy) {
				siblingFacts[0] = analysis.outputFacts(siblingCopy, nodeInput);
			}
			if (node == movedLeftJoin.getRightArg()) {
				movedRightInput[0] = nodeInput;
			}
			if (node == movedLeftJoin.getCondition()) {
				movedConditionInput[0] = nodeInput;
			}
			return true;
		});
		if (movedRightInput[0] == null || siblingFacts[0] == null
				|| leftJoin.hasCondition() && movedConditionInput[0] == null) {
			return false;
		}
		movedFrames.addAll(expressionFrames(analysis, leftJoin.getRightArg(), movedRightInput[0]));
		if (leftJoin.hasCondition()) {
			ValueExpr condition = leftJoin.getCondition();
			movedFrames.add(new ExpressionFrame(condition, movedConditionInput[0],
					analysis.dependencies(condition, movedConditionInput[0])));
		}
		if (sourceFrames.size() != movedFrames.size()) {
			return false;
		}

		if (!overlappingNames.isEmpty()) {
			QueryAlgebraBindingAnalysis.ReadOnlyContext sourceRightInput = analysis.contextAt(leftJoin.getRightArg());
			if (!bindingFactsStableAt(analysis, overlappingNames, sourceRightInput, movedRightInput[0],
					analysis.outputFacts(new SingletonSet(), movedRightInput[0]), siblingFacts[0])) {
				return false;
			}
		}

		for (int i = 0; i < sourceFrames.size(); i++) {
			ExpressionFrame source = sourceFrames.get(i);
			ExpressionFrame moved = movedFrames.get(i);
			if (source.expression().getClass() != moved.expression().getClass()
					|| !sameDependencies(source.dependencies(), moved.dependencies())) {
				return false;
			}
			Set<String> references = dependencyNames(source.dependencies());
			references.addAll(dependencyNames(moved.dependencies()));
			if (!references.isEmpty()
					&& !bindingFactsStableAt(analysis, references, source.input(), moved.input(),
							analysis.outputFacts(new SingletonSet(), moved.input()), siblingFacts[0])) {
				return false;
			}
		}
		return true;
	}

	private List<ExpressionFrame> expressionFrames(QueryAlgebraBindingAnalysis analysis, TupleExpr rightArg,
			QueryAlgebraBindingAnalysis.ReadOnlyContext input) {
		List<ExpressionFrame> frames = new ArrayList<>();
		analysis.visitScoped(rightArg, input, (node, nodeInput) -> {
			if (node instanceof ValueExpr expression && isExpressionRoot(expression)) {
				frames.add(new ExpressionFrame(expression, nodeInput, analysis.dependencies(expression, nodeInput)));
			}
			return true;
		});
		return frames;
	}

	private boolean bindingFactsStableAt(QueryAlgebraBindingAnalysis analysis, Set<String> names,
			QueryAlgebraBindingAnalysis.ReadOnlyContext source,
			QueryAlgebraBindingAnalysis.ReadOnlyContext destinationInput,
			QueryAlgebraBindingAnalysis.OutputFacts destinationFacts,
			QueryAlgebraBindingAnalysis.OutputFacts crossedSiblingFacts) {
		if (analysis.bindingsStableAt(names, source, destinationInput, destinationFacts, crossedSiblingFacts)) {
			return true;
		}
		// The prospective subtree is a structural clone. Scope ids assigned to its cloned scope owners differ, so
		// compare binding facts without ids only when the source and destination are inside those cloned boundaries.
		if (source.scopeIdentity() == destinationInput.scopeIdentity()) {
			return false;
		}
		return analysis.bindingFactsStableAt(names, source, destinationInput, destinationFacts, crossedSiblingFacts);
	}

	private Set<String> dependencyNames(QueryAlgebraBindingAnalysis.Dependencies dependencies) {
		Set<String> names = new HashSet<>(dependencies.directReferences());
		names.addAll(dependencies.correlatedInputs());
		names.addAll(dependencies.existsLocals());
		return names;
	}

	private boolean sameDependencies(QueryAlgebraBindingAnalysis.Dependencies left,
			QueryAlgebraBindingAnalysis.Dependencies right) {
		return left.directReferences().equals(right.directReferences())
				&& left.correlatedInputs().equals(right.correlatedInputs())
				&& left.existsLocals().equals(right.existsLocals());
	}

	private boolean isExpressionRoot(ValueExpr expression) {
		return !(expression.getParentNode() instanceof ValueExpr);
	}

	private record ExpressionFrame(ValueExpr expression, QueryAlgebraBindingAnalysis.ReadOnlyContext input,
			QueryAlgebraBindingAnalysis.Dependencies dependencies) {
	}

	/**
	 * Preserves the legacy visitor behavior for callers that use this public optimizer as a query-model visitor.
	 */
	private boolean isWellDesignedWithoutBindingAnalysis(LeftJoin leftJoin) {
		VarNameCollector optionalVarCollector = new VarNameCollector();
		leftJoin.getRightArg().visit(optionalVarCollector);
		if (leftJoin.hasCondition()) {
			leftJoin.getCondition().visit(optionalVarCollector);
		}

		Set<String> leftBindingNames = leftJoin.getLeftArg().getBindingNames();
		Set<String> problemVars = retainAll(optionalVarCollector.getVarNames(), leftBindingNames);

		if (problemVars.isEmpty()) {
			return true;
		}

		return checkAgainstParent(leftJoin, problemVars);
	}

	private void invalidateAnalysis() {
		QueryAlgebraBindingAnalysis analysis = CURRENT_ANALYSIS.get();
		if (analysis != null) {
			analysis.invalidate();
		}
	}

	private void replacePreservingScope(QueryModelNode source, QueryModelNode replacement) {
		if (source instanceof VariableScopeChange sourceScope && sourceScope.isVariableScopeChange()
				&& replacement instanceof VariableScopeChange replacementScope) {
			replacementScope.setVariableScopeChange(true);
		}
		source.replaceWith(replacement);
		invalidateAnalysis();
	}

	private Set<String> retainAll(Set<String> problemVars, Set<String> leftBindingNames) {
		if (!leftBindingNames.isEmpty() && !problemVars.isEmpty()) {
			if (leftBindingNames.size() > problemVars.size()) {
				for (String problemVar : problemVars) {
					if (leftBindingNames.contains(problemVar)) {
						HashSet<String> ret = new HashSet<>(problemVars);
						ret.removeAll(leftBindingNames);
						return ret;
					}
				}
			} else {
				for (String leftBindingName : leftBindingNames) {
					if (problemVars.contains(leftBindingName)) {
						HashSet<String> ret = new HashSet<>(problemVars);
						ret.removeAll(leftBindingNames);
						return ret;
					}
				}
			}
		}
		return problemVars;
	}

	private boolean checkAgainstParent(LeftJoin leftJoin, Set<String> problemVars) {
		// If any of the problematic variables are bound in the parent
		// expression then the left join is not well designed
		BindingCollector bindingCollector = new BindingCollector();
		QueryModelNode node = leftJoin;
		QueryModelNode parent;
		while ((parent = node.getParentNode()) != null) {
			bindingCollector.setNodeToIgnore(node);
			parent.visitChildren(bindingCollector);
			node = parent;
		}

		Set<String> bindingNames = bindingCollector.getBindingNames();

		for (String problemVar : problemVars) {
			if (bindingNames.contains(problemVar)) {
				return false;
			}
		}

		return true;
	}

	private static class BindingCollector extends AbstractQueryModelVisitor<RuntimeException> {

		private QueryModelNode nodeToIgnore;

		private final Set<String> bindingNames = new HashSet<>();

		public void setNodeToIgnore(QueryModelNode node) {
			this.nodeToIgnore = node;
		}

		public Set<String> getBindingNames() {
			return bindingNames;
		}

		@Override
		protected void meetNode(QueryModelNode node) {
			if (node instanceof TupleExpr tupleExpr && node != nodeToIgnore) {
				bindingNames.addAll(tupleExpr.getBindingNames());
			}
		}
	}
}
